async def act(page):
    """
    - Use the knowledge-base helper `create_curated_collection_by_search` to run the site's visible search for the target article title.
    - From the returned results, find a matching result by case-insensitive substring match on the title.
    - Navigate to the article URL and inspect images using accessibility-role-centric selectors:
        1) try page.get_by_role('img', name='iPad Mini')
        2) if none, iterate all role='img' elements (guarded by count()) and inspect alt/title/src attributes for 'ipad mini' or both words present
    - Print exactly 'Yes' if found, otherwise print exactly 'No'.
    """

    # Use the site-aware helper to perform the visible search. The helper will navigate to '/'.
    try:
        results = await create_curated_collection_by_search(
            page,
            "Ruby 4.0 update brings ZJIT, isolation features, and more",
            max_results=50,
            resolve_links=True,
        )
    except Exception:
        # If the helper fails, conservatively report No
        print("No")
        return

    # Find the best matching result by title (case-insensitive substring match)
    target = None
    needle = "ruby 4.0 update brings zjit"
    if isinstance(results, list):
        for r in results:
            if not isinstance(r, dict):
                continue
            title = (r.get("title") or "").strip()
            if not title:
                continue
            if needle in title.lower():
                target = r
                break
        if not target:
            # shorter fallback
            for r in results:
                if not isinstance(r, dict):
                    continue
                title = (r.get("title") or "").strip()
                if "ruby 4.0" in title.lower():
                    target = r
                    break

    if not target:
        # Article not found via the site's search
        print("No")
        return

    url = target.get("url") if isinstance(target, dict) else None
    if not url:
        print("No")
        return

    # Navigate to the article page
    try:
        await page.goto(url)
    except Exception:
        print("No")
        return

    # Wait for main region or fallback to networkidle to allow content to load
    try:
        await page.get_by_role("main").wait_for(timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state("networkidle")
        except Exception:
            pass

    # 1) Try accessible-name-based lookup for an image whose accessible name contains 'iPad Mini'
    try:
        img_by_name = page.get_by_role("img", name="iPad Mini")
        if await img_by_name.count() > 0:
            print("Yes")
            return
    except Exception:
        # fall-through to attribute inspection
        pass

    # 2) Fallback: iterate all role='img' elements and inspect attributes
    imgs = page.get_by_role("img")
    try:
        img_count = await imgs.count()
    except Exception:
        img_count = 0

    found = False
    for i in range(img_count):
        img = imgs.nth(i)
        try:
            alt = await img.get_attribute("alt") or ""
        except Exception:
            alt = ""
        try:
            title_attr = await img.get_attribute("title") or ""
        except Exception:
            title_attr = ""
        try:
            src = await img.get_attribute("src") or ""
        except Exception:
            src = ""

        combined = f"{alt} {title_attr} {src}".lower()
        if "ipad mini" in combined or ("ipad" in combined and "mini" in combined):
            found = True
            break

    print("Yes" if found else "No")

